header.script:
document.addEventListener('DOMContentLoaded', function () {
  if (!window.predictiveSearchEnabled) {

    document.querySelectorAll('search-drawer').forEach(function (btn) {
      btn.addEventListener('click', function (e) {
        e.preventDefault();
        window.location.href = "/search";
      });
    });

  }
});

body.script:
class ScrollToBack extends HTMLElement{
  constructor() {
        super(), 
          this.pageHeight = window.innerHeight
    }


    connectedCallback() {
        this.addEventListener("click", this.onClick), this.addEventListener("touchstart", this.onClick, {
            passive: !0
        }), window.addEventListener("scroll", this.checkVisible.bind(this))
    }
    checkVisible(event) {
        window.requestAnimationFrame(() => {
            window.scrollY > this.pageHeight ? this.classList.add("back-to-top--active") : this.classList.remove("back-to-top--active")
        })

        let scrollProgress = document.getElementById("scroll-to-top");
        let progressValue = document.getElementById("backtoscroll-value");
        let pos = document.documentElement.scrollTop;
        let calcHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        let scrollValue = Math.round((pos * 100) / calcHeight);
        if (pos > 200) {
            scrollProgress.style.display = "grid";
        } else {
            scrollProgress.style.display = "none";
        }
        scrollProgress.style.background = `conic-gradient(var(--scroll-top-color) ${scrollValue}%, var(--scroll-top-background) ${scrollValue}%)`;
    }
    onClick() {
        window.scrollTo({
            top: 0,
            left: 0,
            behavior: "smooth"
        })
  }
}
customElements.define("scroll-to-back", ScrollToBack);
